&lt;li class=&quot;p1&quot; style=&quot;font-size: 12pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: helvetica, arial, sans-serif;&quot;&gt;Maintain workflow eSiciency and product integrity.&lt;/span&gt;&lt;/li&gt;
&lt;li class=&quot;p1&quot; style=&quot;font-size: 12pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: helvetica, arial, sans-serif;&quot;&gt;Verify counts and pack order accuracy.&lt;/span&gt;&lt;/li&gt;
&lt;li class=&quot;p1&quot; style=&quot;font-size: 12pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: helvetica, arial, sans-serif;&quot;&gt;Communicate with Supervisors on rework priorities.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p class=&quot;p1&quot;&gt;&amp;nbsp;&lt;/p&gt;
&lt;p class=&quot;p1&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-size: 12pt; font-family: helvetica, arial, sans-serif;&quot;&gt;Qualifications &amp;amp; Experience:&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
