&lt;li class=&quot;p1&quot; style=&quot;font-size: 12pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: helvetica, arial, sans-serif;&quot;&gt;Leadership or training experience preferred.&lt;/span&gt;&lt;/li&gt;
